import { useState } from 'react';

const INITIAL = [
  { id: 1, name: 'Spell Tome', price: 30, qty: 2 },
  { id: 2, name: 'Magic Staff', price: 150, qty: 1 },
];

export default function CartSummary() {
  const [items, setItems] = useState(INITIAL);

  // TODO: derive itemCount, totalQty, totalPrice from items

  function handleAdd() {
    setItems(prev => [...prev, { id: Date.now(), name: 'Potion', price: 5, qty: 1 }]);
  }

  return (
    <div>
      {/* TODO: render item list */}
      <p data-testid="item-count">{/* itemCount */}</p>
      <p data-testid="total-qty">{/* totalQty */}</p>
      <p data-testid="total-price">{/* totalPrice */}</p>
      <button data-testid="add" onClick={handleAdd}>Add Item</button>
    </div>
  );
}
